pragma solidity ^0.8.24;

import {IDrillProofTypes} from "./IDrillProofTypes.sol";

interface IProjectAdapter {
    function expectedProjectKey() external view returns (bytes32 projectKey);

    function normalizeSubmission(
        bytes32 projectKey,
        IDrillProofTypes.AdapterPayload calldata payload,
        string calldata uri,
        bytes32 parentDatasetHash,
        address submitter
    ) external view returns (IDrillProofTypes.CanonicalDatasetInput memory canonicalInput);
}

contracts/core/DrillProofAccess.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {DrillProofErrors} from "../libraries/DrillProofErrors.sol";

contract DrillProofAccess is AccessControl, Pausable {
    bytes32 public constant PROJECT_ADMIN_ROLE = keccak256("PROJECT_ADMIN_ROLE");
    bytes32 public constant VALIDATOR_ROLE = keccak256("VALIDATOR_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    constructor(address admin) {
        if (admin == address(0)) revert DrillProofErrors.ZeroAddress();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(PROJECT_ADMIN_ROLE, admin);
        _grantRole(VALIDATOR_ROLE, admin);
        _grantRole(AUDITOR_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

